import hashlib
import hmac
import struct
import time
import os
from flask import Flask, request, jsonify, abort
from functools import wraps
import sqlite3

app = Flask(__name__)
SECRET_KEY = os.environ.get('TOKEN_SECRET')
if not SECRET_KEY:
    raise RuntimeError(
        'TOKEN_SECRET environment variable must be set to a strong, unique secret. '
        'Refusing to start with a missing or default signing key.'
    )
DB_PATH = os.environ.get('DB_PATH', '/app/data/users.db')

def get_db():
    conn = sqlite3.connect(DB_PATH)
    conn.row_factory = sqlite3.Row
    return conn

def init_db():
    conn = get_db()
    conn.execute('''CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY,
        username TEXT UNIQUE NOT NULL,
        role TEXT NOT NULL DEFAULT 'user',
        api_quota INTEGER DEFAULT 100
    )''')
    conn.execute('''CREATE TABLE IF NOT EXISTS audit_log (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        user_id INTEGER,
        action TEXT,
        timestamp INTEGER
    )''')
    conn.commit()
    conn.close()

class TokenEngine:
    """Custom binary token format for high-performance API authentication.
    Token structure: [version:1][user_id:4][role_bits:2][timestamp:4][quota_remaining:4][hmac:32]
    Total: 47 bytes
    """
    VERSION = 0x02
    ROLE_USER = 0x0001
    ROLE_ADMIN = 0x8000
    ROLE_SERVICE = 0x4000

    @staticmethod
    def _compute_hmac(payload):
        return hmac.new(SECRET_KEY.encode(), payload, hashlib.sha256).digest()

    @staticmethod
    def create_token(user_id, role_bits, quota):
        timestamp = int(time.time())
        payload = struct.pack('>BIHII', TokenEngine.VERSION, user_id, role_bits, timestamp, quota)
        mac = hmac.new(SECRET_KEY.encode(), payload, hashlib.sha256).digest()
        return (payload + mac).hex()

    @staticmethod
    def parse_token(token_hex):
        try:
            token_bytes = bytes.fromhex(token_hex)
        except (ValueError, TypeError):
            return None

        if len(token_bytes) != 47:
            return None

        payload = token_bytes[:15]
        provided_mac = token_bytes[15:]

        expected_mac = hmac.new(SECRET_KEY.encode(), payload, hashlib.sha256).digest()
        if not hmac.compare_digest(provided_mac, expected_mac):
            return None

        version, user_id, role_bits, timestamp, quota = struct.unpack('>BIHiI', payload)

        if version != TokenEngine.VERSION:
            return None

        current_time = int(time.time())
        if timestamp > current_time:
            return None

        token_age = current_time - timestamp
        if token_age > 86400:  # 24 hour expiry
            return None

        return {
            'user_id': user_id,
            'role_bits': role_bits,
            'timestamp': timestamp,
            'quota': quota
        }

    @staticmethod
    def check_permission(token_data, required_role):
        """Check if token has required role permission.
        Uses bitwise AND to check role flags.
        Admin (0x8000) has access to everything.
        """
        if token_data is None:
            return False

        user_roles = token_data['role_bits']

        # Validate role_bits is within valid range for unsigned 16-bit
        if not (0 <= user_roles <= 0xFFFF):
            return False

        # Admin override: if admin bit is set, grant all access
        if user_roles & TokenEngine.ROLE_ADMIN:
            return True

        # Check specific role bit
        if user_roles & required_role:
            return True

        return False

def require_auth(required_role=None):
    def decorator(f):
        @wraps(f)
        def decorated(*args, **kwargs):
            token_hex = request.headers.get('X-API-Token', '')
            token_data = TokenEngine.parse_token(token_hex)

            if token_data is None:
                abort(401)

            if required_role is not None:
                if not TokenEngine.check_permission(token_data, required_role):
                    abort(403)

            request.token_data = token_data
            return f(*args, **kwargs)
        return decorated
    return decorator

@app.route('/api/user/profile', methods=['GET'])
@require_auth(required_role=TokenEngine.ROLE_USER)
def get_profile():
    user_id = request.token_data['user_id']
    conn = get_db()
    user = conn.execute('SELECT * FROM users WHERE id = ?', (user_id,)).fetchone()
    conn.close()
    if user:
        return jsonify({'id': user['id'], 'username': user['username'], 'role': user['role']})
    return jsonify({'error': 'not found'}), 404

@app.route('/api/admin/users', methods=['GET'])
@require_auth(required_role=TokenEngine.ROLE_ADMIN)
def list_users():
    conn = get_db()
    users = conn.execute('SELECT id, username, role FROM users').fetchall()
    conn.close()
    return jsonify([dict(u) for u in users])

@app.route('/api/admin/quota', methods=['POST'])
@require_auth(required_role=TokenEngine.ROLE_ADMIN)
def update_quota():
    data = request.get_json()
    if not data or 'user_id' not in data or 'quota' not in data:
        abort(400)
    conn = get_db()
    conn.execute('UPDATE users SET api_quota = ? WHERE id = ?', (data['quota'], data['user_id']))
    conn.commit()
    conn.close()

    # Audit log
    audit_conn = get_db()
    audit_conn.execute('INSERT INTO audit_log (user_id, action, timestamp) VALUES (?, ?, ?)',
                       (request.token_data['user_id'], f"quota_update:{data['user_id']}:{data['quota']}", int(time.time())))
    audit_conn.commit()
    audit_conn.close()
    return jsonify({'status': 'updated'})

@app.route('/api/service/health', methods=['GET'])
@require_auth(required_role=TokenEngine.ROLE_SERVICE)
def health_check():
    return jsonify({'status': 'healthy', 'timestamp': int(time.time())})

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=8080)
